<div class="grid"><div class="card"><h2><?= e(t('Users')) ?></h2><ul><?php foreach($users as $u): ?><li><a href="/backups?user=<?= urlencode($u) ?>"><?= e($u) ?></a></li><?php endforeach ?></ul></div><div class="card"><h2><?= e(t('Backup dates')) ?></h2><table><tr><th><?= e(t('User')) ?></th><th><?= e(t('Date')) ?></th><th><?= e(t('Type')) ?></th><th><?= e(t('Path')) ?></th></tr><?php foreach($backups as $b): ?><tr><td><?= e($b['user']) ?></td><td><?= e($b['date']) ?></td><td><?= e($b['type']) ?></td><td><code><?= e($b['path']) ?></code></td></tr><?php endforeach ?></table></div></div>
<div class="card"><h2><?= e(t('Find selected file in backups')) ?></h2><form><input class="input" style="width:55%" name="path" placeholder="/var/www/user/data/www/site/index.php" value="<?= e($searchPath) ?>"> <input class="input" name="date" placeholder="YYYY-MM-DD" value="<?= e($date) ?>"> <button class="btn"><?= e(t('Search')) ?></button></form><?php if($found): ?><table><tr><th><?= e(t('Date')) ?></th><th><?= e(t('Type')) ?></th><th><?= e(t('Source')) ?></th><th><?= e(t('Size')) ?></th><th>mtime</th><th><?= e(t('Actions')) ?></th></tr><?php foreach($found as $f): ?><tr><td><?= e($f['date']) ?></td><td><?= e($f['backup_type']) ?></td><td><code><?= e($f['source']) ?></code></td><td><?= e($f['size']) ?></td><td><?= e($f['mtime']) ?></td><td><a class="btn small" href="/backups?path=<?= urlencode($searchPath) ?>&date=<?= urlencode($f['date']) ?>"><?= e(t('Preview/Diff')) ?></a></td></tr><?php endforeach ?></table><?php elseif($searchPath): ?><p class="muted"><?= e(t('File not found in currently browsable backup folders. Native ISPmanager tools should be preferred for archive/differential chains.')) ?></p><?php endif ?></div>
<?php if($preview !== null): ?><div class="card"><h2><?= e(t('Preview / Diff')) ?></h2><p><b><?= e(t('Current file:')) ?></b> <code><?= e($searchPath) ?></code></p><p><b><?= e(t('Backup date:')) ?></b> <?= e($date) ?></p><h3><?= e(t('Diff')) ?></h3><pre><?= e($diff) ?></pre><h3><?= e(t('Backup preview')) ?></h3><pre><?= e($preview) ?></pre><?php $cmd='php artisan guard:backups:restore-file --path='.escapeshellarg($searchPath).' --date='.escapeshellarg($date); ?><h3><?= e(t('Restore')) ?></h3><?php if(!config('guard.backup_restore_enabled')): ?><p class="muted"><?= e(t('Web restore is disabled. Run this CLI command after confirmation:')) ?></p><pre><?= e($cmd) ?></pre><?php else: ?><p><?= e(t('Use CLI for audited selective restore:')) ?> <code><?= e($cmd) ?></code></p><?php endif ?></div><?php endif ?>
